types.decl:
typedef void (*ecuio_frame_callback_t)(
    const ecuio_frame_t* frame,
    void* user_data
);

typedef struct ecuio_session_info {
    uint32_t flags;           /* ECUIO_SESSION_INFO_* */
    uint32_t backend;         /* ECUIO_BACKEND_* */
    uint32_t dll_arch;        /* ECUIO_DLL_ARCH_*; UNKNOWN for mock */
    uint32_t protocol_id;     /* the J2534 ProtocolID the channel connected
                                 with (6 = ISO 15765); 0 for mock */
    uint32_t baud;            /* bit/s it connected at; 0 for mock */
    uint32_t connect_flags;   /* PassThruConnect's Flags: ?flags=, plus
                                 CAN_29BIT_ID (0x100) for 29-bit channels */
    uint32_t vbatt_mv;        /* battery voltage at connect, millivolts
                                 (READ_VBATT); with ECUIO_SESSION_INFO_VBATT */
    uint32_t channel_count;   /* CAN channels the session filters and
                                 requests on; 0 for a passive session */
    uint32_t rx_ids[ECUIO_SESSION_INFO_MAX_CHANNELS];   /* each one's
                                                           receive ID */
    uint32_t tx_ids[ECUIO_SESSION_INFO_MAX_CHANNELS];   /* and transmit ID */
    /* The adapter's firmware, its DLL and the J2534 API version it
     * implements (PassThruReadVersion), each NUL-terminated on one line;
     * "" without ECUIO_SESSION_INFO_VERSIONS. */
    char firmware_version[ECUIO_SESSION_INFO_TEXT_LEN];
    char dll_version[ECUIO_SESSION_INFO_TEXT_LEN];
    char api_version[ECUIO_SESSION_INFO_TEXT_LEN];
    /* The profile the session decodes through (ADR-0013): ?profile=, or
     * the scheme's default. NUL-terminated. */
    char profile[ECUIO_SESSION_INFO_PROFILE_LEN];
    uint32_t reserved[16];    /* zero; ABI growth space */
} ecuio_session_info_t;

typedef struct ecuio_transport_ops {
    ecuio_status_t (*start)(ecuio_session_t* session, void* impl);
    void (*detach)(ecuio_session_t* session, void* impl);
} ecuio_transport_ops_t;

typedef struct ecuio_transport {
    const ecuio_transport_ops_t* ops;
    void* impl;
} ecuio_transport_t;

typedef struct ecuio_pt_sconfig {
    unsigned long Parameter;   /* config parameter name (e.g. DATA_RATE) */
    unsigned long Value;      /* parameter value */
} SCONFIG;

typedef struct ecuio_pt_sconfig_list {
    unsigned long NumOfParams;
    SCONFIG* ConfigPtr;
} SCONFIG_LIST;

typedef struct ecuio_pt_passthru_msg {
    unsigned long ProtocolID;
    unsigned long RxStatus;
    unsigned long TxFlags;
    unsigned long Timestamp;       /* microseconds (spec v4.04; vendor
                                    * conformance is a BENCH check) */
    unsigned long DataSize;        /* payload bytes in Data[] */
    unsigned long ExtraDataIndex;  /* start of extra data (CRC, etc.);
                                    * == DataSize when none */
    unsigned char  Data[ECUIO_PT_MSG_DATA_SIZE];
} PASSTHRU_MSG;

typedef enum {
    ECUIO_VALUE_UINT  = 0,
    ECUIO_VALUE_INT   = 1,   /* two's complement, sign-extended from bit_length */
    ECUIO_VALUE_FLOAT = 2,   /* IEEE-754 binary32 */
    ECUIO_VALUE_TEXT  = 3    /* reserved: no decoder yet */
} ecuio_value_kind_t;

typedef struct ecuio_signal_def {
    uint16_t id;
    uint16_t reserved0;           /* zero */

    /* Match. ecuio_def_applies_to_frame checks both before decode, and
     * ecuio_decode_signal checks the key again. */
    uint32_t message_id;          /* the frame's arbitration_id must equal it */
    uint8_t  mux_offset;          /* payload byte where the key starts */
    uint8_t  mux_length;          /* 0 = no mux; 1 to 3 = key bytes */
    uint8_t  mux_reserved[2];     /* zero */
    uint32_t mux_key;             /* key bytes, first byte most significant,
                                     whatever byte_order says */

    /* Decode */
    uint8_t  kind;                /* ecuio_value_kind_t */
    uint8_t  byte_order;          /* ECUIO_BYTE_ORDER_* */
    uint16_t start_byte;
    uint8_t  bit_offset;          /* 0..7; 0 for BE and FLOAT */
    uint8_t  bit_length;          /* 1..32; 32 for FLOAT; whole bytes for BE */
    uint8_t  decode_reserved[2];  /* zero */
    double   scale;
    double   offset;              /* value = raw * scale + offset, in double */

    /* Display. UIs show the strings as they are. */
    char     name[32];            /* UTF-8, terminated inside the buffer */
    char     unit[16];            /* UTF-8 (a degree sign, "km/h"), terminated */
    uint8_t  decimal_places;      /* 0..3 */
    uint8_t  display_reserved[3]; /* zero */

    uint32_t flags;               /* none defined; zero */
    uint32_t reserved[6];         /* zero; ADR-0016 earmarks this room */
} ecuio_signal_def_t;

typedef struct ecuio_channel_decl {
    uint32_t rx_id;   /* flow-control filter target */
    uint32_t tx_id;   /* request destination */
} ecuio_channel_decl_t;

typedef struct ecuio_signal_set {
    uint32_t layout_version;      /* ECUIO_SIGNAL_SET_LAYOUT; the first member, always */
    uint32_t count;
    const ecuio_signal_def_t* defs;
    uint32_t channel_count;       /* 0 with NULL channels: none declared */
    uint32_t reserved0;           /* zero */
    const ecuio_channel_decl_t* channels;
    uint32_t reserved[4];         /* zero */
} ecuio_signal_set_t;

typedef struct ecuio_validation {
    int32_t  code;                /* ECUIO_VALIDATE_*; 0 = OK */
    uint32_t index;               /* the def or channel, or UINT32_MAX */
    uint32_t reserved[2];         /* written as zero */
} ecuio_validation_t;

typedef struct ecuio_sur_request {
    uint32_t request_id;   /* client-assigned, increasing; echoed back */
    uint32_t opcode;       /* ECUIO_SUR_OP_* */
    union {
        struct { uint32_t fingerprint; } open;
        struct { uint32_t protocol_id; uint32_t flags; uint32_t baud; } connect;
        struct { uint32_t channel_id; } disconnect;
        /* input: flattened SCONFIG pairs (u32 Parameter, u32 Value, LE)
         * for GET/SET_CONFIG; input_len 0 for NULL-input ioctls. */
        struct { uint32_t channel_id; uint32_t ioctl_id;
                 uint8_t input[ECUIO_SUR_IOCTL_DATA_MAX];
                 uint32_t input_len; } ioctl;
        struct { uint32_t channel_id;
                 uint8_t data[ECUIO_SUR_MSG_MAX];
                 uint32_t data_len; uint32_t tx_flags;
                 uint32_t timeout_ms; } write;
        /* The vendor's ReadMsgs timeout. The client waits that plus
         * 500 ms for the reply before it calls the child hung. */
        struct { uint32_t timeout_ms; } read;
        struct { uint8_t data[ECUIO_SUR_MSG_MAX]; uint32_t len;
                 uint32_t timestamp; uint32_t rx_flags; } inject;
        struct { uint32_t channel_id; uint32_t filter_type; uint32_t tx_flags;
                 uint8_t mask[ECUIO_SUR_FILTER_PATTERN_MAX];
                 uint8_t pattern[ECUIO_SUR_FILTER_PATTERN_MAX];
                 uint8_t flow_control[ECUIO_SUR_FILTER_PATTERN_MAX];
                 uint32_t mask_len; uint32_t pattern_len; uint32_t fc_len;
                 } start_filter;
        struct { uint32_t channel_id; uint32_t filter_id; } stop_filter;
    } u;
} ecuio_sur_request_t;

typedef struct ecuio_sur_frame {
    uint32_t arbitration_id;  /* always 0: the CAN ID is data[0..3], which
                                 the transport strips (ADR-0012) */
    uint32_t timestamp;       /* the vendor's Timestamp, untranslated: the
                                 transport makes it session time */
    uint32_t rx_flags;        /* the vendor's RxStatus */
    uint8_t  data[ECUIO_SUR_MSG_MAX];
    uint8_t  data_len;        /* the child clamps to ECUIO_SUR_MSG_MAX */
} ecuio_sur_frame_t;

typedef struct ecuio_sur_response {
    uint32_t request_id;         /* the request's, for pairing */
    int32_t  status;             /* vendor J2534 status, or STATUS_FAILED */
    uint32_t handle_or_channel;  /* CONNECT: channel ID; START_FILTER: filter ID */
    uint32_t aux;                /* OPEN: the child's fingerprint; WRITE: messages written */
    /* GET_LAST_ERROR: [0]; READ_VERSION: all three. The client
     * terminates each. */
    char     text[ECUIO_SUR_TEXT_FIELDS][ECUIO_SUR_TEXT_MAX];
    uint8_t  data[ECUIO_SUR_IOCTL_DATA_MAX];   /* IOCTL reply payload */
    uint32_t data_len;           /* IOCTL; the client rejects > the limit */
    uint32_t num_frames;         /* READ; the client rejects > the limit */
    ecuio_sur_frame_t frames[ECUIO_SUR_MAX_FRAMES_PER_READ];
} ecuio_sur_response_t;

typedef struct ecuio_pid_scheduler {
    uint8_t pids[ECUIO_SCHED_MAX_PIDS];
    uint32_t count;
    uint32_t cursor;
} ecuio_pid_scheduler;

typedef void (*fn_get_last_filter_start)(unsigned long*, unsigned long*,
                                         unsigned char*, unsigned char*,
                                         unsigned long*);
